B.ab0=new A.t("ec-m3-q8","\u0645\u0627 \u0627\u0644\u063a\u0631\u0636 \u0645\u0646 \xab\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0623\u0645\u0627\u0646\xbb\u061f","What is the purpose of safety stock?",B.aeC,B.aA8,0,"\u062a\u062c\u0627\u0647\u0644\u0647 \u064a\u0639\u0646\u064a \u0646\u0641\u0627\u062f\u064b\u0627 \u0645\u062a\u0643\u0631\u0631\u064b\u0627 \u0641\u064a \u0623\u0641\u0636\u0644 \u0623\u0635\u0646\u0627\u0641\u0643 \u2014 \u0648\u0647\u0648 \u0623\u0633\u0648\u0623 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0646\u0641\u0627\u062f. \u0648\u064a\u0642\u0641 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u0647 \u0646\u0638\u0627\u0645 \u0627\u0644\u0631\u0645\u0648\u0632 (SKU): \u0631\u0645\u0632 \u0641\u0631\u064a\u062f \u0644\u0643\u0644 \u0635\u0646\u0641 \u0628\u0643\u0644 \u0645\u0642\u0627\u0633 \u0648\u0644\u0648\u0646\u060c \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u0645\u062a\u062c\u0631 \u0648\u062c\u062f\u0648\u0644 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0648\u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0645\u0648\u0631\u0651\u062f \u0648\u0645\u0644\u0635\u0642 \u0627\u0644\u0631\u0641\u060c \u0648\u0628\u062f\u0648\u0646\u0647 \u0633\u062a\u0628\u064a\u0639 \u0645\u0642\u0627\u0633\u064b\u0627 \u0646\u0641\u062f.","Ignoring it means repeated stockouts on your best sellers \u2014 the worst kind of stockout. Beside it stands the SKU system: a unique code for every item in every size and colour, used in the store, the stock sheet, the supplier invoice and the shelf label. Without it you will sell a size that ran out.")
B.anG=s(["\u0639\u0631\u0636 \u062a\u062c\u0627\u0631\u064a \u0645\u0634\u0631\u0648\u0639 \u0645\u0627 \u062f\u0627\u0645 \u0627\u0644\u0645\u0646\u062a\u062c \u0645\u0648\u062c\u0648\u062f\u064b\u0627","\u0646\u0645\u0637\u0627\u0646 \u0645\u0646 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0636\u0644\u064a\u0644 \u0645\u0639\u064b\u0627\u060c \u0648\u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u0627\u0644\u0647\u0631\u0645\u064a\u0629 \u0645\u0646\u0647 \u0625\u0644\u0649 \u0627\u0644\u062a\u062c\u0627\u0631\u0629","\u062a\u0633\u0648\u064a\u0642 \u0628\u0627\u0644\u0639\u0645\u0648\u0644\u0629 \u0639\u0627\u062f\u064a \u0648\u0645\u0639\u0631\u0648\u0641","\u0634\u0631\u0627\u0643\u0629 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0651\u0628 \u0648\u0627\u0644\u0645\u0648\u0631\u062f\u064a\u0646"],t.s)
