B.abg=new A.t("ec-m7-q7","\u0645\u0646 \u0623\u064a\u0646 \u062a\u064f\u062d\u0633\u0628 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0634\u062d\u0646 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u0644\u0643\u0644 \u0637\u0644\u0628\u061f","Where does your real shipping cost per order come from?",B.ayy,B.ael,1,"\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0645\u0639\u0644\u0646 \u0646\u0627\u062f\u0631\u064b\u0627 \u0645\u0627 \u064a\u0643\u0648\u0646 \u0645\u0627 \u062a\u062f\u0641\u0639\u0647 \u0641\u0639\u0644\u064b\u0627: \u062a\u064f\u0636\u0627\u0641 \u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0646\u0627\u0626\u064a\u0629\u060c \u0648\u0631\u0633\u0648\u0645 \u0627\u0644\u062f\u0641\u0639 \u0639\u0646\u062f \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645\u060c \u0648\u0631\u0633\u0648\u0645 \u0627\u0644\u0625\u0639\u0627\u062f\u0629 \u0644\u0644\u0645\u0631\u0633\u0644\u060c \u0648\u0627\u0644\u0636\u0631\u064a\u0628\u0629\u060c \u0648\u0627\u0644\u062a\u0623\u0645\u064a\u0646 \u0625\u0646 \u0627\u0633\u062a\u064f\u062e\u062f\u0645. \u0648\u0627\u0644\u0641\u062c\u0648\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u0642\u0645\u064a\u0646 \u0647\u064a \u0623\u0648\u0644 \u062a\u0633\u0631\u064a\u0628 \u062a\u0643\u062a\u0634\u0641\u0647 \u0623\u063a\u0644\u0628 \u0627\u0644\u0645\u062a\u0627\u062c\u0631.","The advertised rate is rarely what you actually pay: add remote-area surcharges, COD fees, return-to-sender fees, VAT and insurance if used. The gap between those two numbers is the first leak most stores find.")
B.auf=s(["\u0627\u0644\u0646\u0634\u0631 \u0628\u0645\u0639\u062f\u0644 \u0642\u0644\u064a\u0644 \u062c\u062f\u064b\u0627","\u0646\u0634\u0631 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0645\u062a\u0643\u0631\u0631\u0629 \u0641\u064a \u0647\u064a\u0626\u0629 \u0645\u062d\u062a\u0648\u0649\u060c \u0648\u0627\u0644\u062c\u0645\u0647\u0648\u0631 \u064a\u0645\u064a\u0651\u0632 \u0627\u0644\u0641\u0631\u0642 \u0633\u0631\u064a\u0639\u064b\u0627","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0635\u0648\u0631 \u0627\u0644\u0645\u0646\u062a\u062c \u0628\u062f\u0644 \u0627\u0644\u0641\u064a\u062f\u064a\u0648","\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0641\u0635\u062d\u0649"],t.s)
