B.a8i=new A.t("ec-m8-q3","\u0645\u0627 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0639\u0645\u0644\u064a \u0627\u0644\u0630\u064a \u064a\u0648\u0635\u064a \u0628\u0647 \u0627\u0644\u062f\u0644\u064a\u0644 \u0644\u0623\u063a\u0644\u0628 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646 \u0628\u064a\u0646 \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0627\u0644\u0645\u062a\u062c\u0631 \u0627\u0644\u062e\u0627\u0635\u061f","What practical path does the guide recommend for most beginners between a marketplace and their own store?",B.aBc,B.ajG,1,"\u0648\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u063a\u0631\u0636\u0647 \u0628\u0646\u0627\u0621 \u0639\u0644\u0627\u0642\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0648\u0642\u0627\u0626\u0645\u0629 \u0628\u0631\u064a\u062f\u064a\u0629 \u062a\u0645\u0644\u0643\u0647\u0627. \u0648\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0627\u062b\u0646\u064a\u0646 \u0645\u0639\u064b\u0627 \u062e\u064a\u0627\u0631 \u0634\u0627\u0626\u0639 \u0648\u0645\u0634\u0631\u0648\u0639\u060c \u0644\u0627 \u062a\u0646\u0627\u0642\u0636 \u0641\u064a\u0647.","The move exists to build a direct relationship and an email list you own. And running both at once is a common and legitimate choice, with no contradiction in it.")
B.ahJ=s(["\u0623\u0644\u0627 \u062a\u0646\u0641\u0642 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0647\u0627\u0645\u0634 \u0645\u0633\u0627\u0647\u0645\u062a\u0643 \u0644\u0644\u0637\u0644\u0628 \u0625\u0644\u0627 \u0628\u0642\u0631\u0627\u0631 \u0645\u062f\u0631\u0648\u0633 \u064a\u0633\u0646\u062f\u0647 \u0645\u0639\u062f\u0644 \u062a\u0643\u0631\u0627\u0631 \u0645\u0642\u064a\u0633","\u0623\u0646 \u062a\u0646\u0641\u0642 \u0646\u0635\u0641 \u0633\u0639\u0631 \u0627\u0644\u0645\u0646\u062a\u062c \u062f\u0627\u0626\u0645\u064b\u0627","\u0623\u0646 \u062a\u0646\u0641\u0642 \u0645\u0627 \u062a\u0646\u0641\u0642\u0647 \u0627\u0644\u0645\u062a\u0627\u062c\u0631 \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u0629","\u0623\u0646 \u062a\u0646\u0641\u0642 \u062d\u062a\u0649 \u064a\u0631\u062a\u0641\u0639 \u0639\u062f\u062f \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u062b\u0645 \u062a\u0642\u064a\u0633"],t.s)
