B.a9E=new A.t("ec-m9-q3","\u0623\u064a \u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a \u064a\u0633\u062a\u062f\u0639\u064a \u062a\u062d\u0642\u0642\u064b\u0627 \u062a\u0646\u0638\u064a\u0645\u064a\u064b\u0627 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0644\u0627 \u0628\u0639\u062f\u0647\u061f","Which products call for a regulatory check before importing rather than after?",B.ajn,B.arg,1,"\u0647\u0630\u0647 \u0641\u0626\u0627\u062a \u062a\u062a\u0637\u0644\u0628 \u0645\u0648\u0627\u0641\u0642\u0627\u062a \u062a\u0633\u0628\u0642 \u0627\u0644\u0628\u064a\u0639. \u0648\u0627\u0628\u062f\u0623 \u0645\u0646 \u0627\u0644\u0628\u0648\u0627\u0628\u0627\u062a \u0627\u0644\u062d\u0643\u0648\u0645\u064a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0635\u062d\u064a\u062d \u0648\u0645\u062a\u0637\u0644\u0628\u0627\u062a\u0647\u060c \u062b\u0645 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0637\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0645\u0646\u062a\u062c\u0643 \u0642\u0628\u0644 \u0627\u0644\u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0644\u0627 \u0628\u0639\u062f\u0647 \u2014 \u0648\u0627\u0644\u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0644\u0647 \u062c\u0627\u0646\u0628 \u062c\u0645\u0631\u0643\u064a \u064a\u062f\u062e\u0644 \u0641\u064a \u062a\u0643\u0644\u0641\u0629 \u0628\u0636\u0627\u0639\u062a\u0643.","These categories require approvals before selling. Start from the official government portals to identify the correct activity and its requirements, then check any category-specific conditions for your product before importing rather than after \u2014 and importing has a customs side that enters your goods cost.")
B.arr=s(["\u062f\u0627\u0626\u0645\u064b\u0627\u060c \u0644\u0623\u0646 \u0627\u0644\u0639\u0645\u064a\u0644 \u0627\u0644\u062c\u062f\u064a\u062f \u0623\u0647\u0645 \u0645\u0646 \u0627\u0644\u0631\u0628\u062d","\u062d\u064a\u0646 \u064a\u0639\u0648\u062f \u0627\u0644\u0639\u0645\u064a\u0644 \u0641\u0639\u0644\u064b\u0627\u060c \u0628\u0645\u0639\u062f\u0644 \u062a\u0643\u0631\u0627\u0631 \u0645\u0642\u064a\u0633 \u0645\u0646 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0648\u0633\u064a\u0648\u0644\u0629 \u062a\u063a\u0637\u064a \u0627\u0644\u0641\u062c\u0648\u0629","\u062d\u064a\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0646\u062a\u062c \u062c\u062f\u064a\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u0633\u0648\u0642","\u062d\u064a\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u0629 \u0634\u062f\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0641\u0626\u0629"],t.s)
B.atT=s(["Always, since a new customer matters more than profit","When the customer genuinely returns, with a repeat rate measured from your data and liquidity covering the gap","When the product is new to the market","When competition in the category is fierce"],t.s)
B.a8E=new A.t("ec-m9-q4","\u0645\u062a\u0649 \u064a\u064f\u0633\u0645\u062d \u0628\u0627\u0644\u062e\u0633\u0627\u0631\u0629 \u0627\u0644\u0645\u062a\u0639\u0645\u064e\u0651\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0623\u0648\u0644\u061f","When is a deliberate loss on the first order allowed?",B.arr,B.atT,1,"\u0628\u0639\u0636 \u0627\u0644\u0645\u062a\u0627\u062c\u0631 \u062a\u062e\u0633\u0631 \u0639\u0645\u062f\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0623\u0648\u0644 \u0644\u0623\u0646 \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0639\u0648\u062f\u060c \u0648\u0647\u0630\u0647 \u062d\u0633\u0628\u0629 \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u062f\u0627\u0626\u0645\u0629. \u0644\u0643\u0646 \u0628\u0634\u0631\u0637\u064a\u0646 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644\u064a\u0646 \u0644\u0644\u062a\u0641\u0627\u0648\u0636: \u062a\u0643\u0631\u0627\u0631 \u0645\u0642\u064a\u0633 \u0644\u0627 \u0645\u0641\u062a\u0631\u0636\u060c \u0648\u0633\u064a\u0648\u0644\u0629 \u0643\u0627\u0641\u064a\u0629. \u0648\u0628\u063a\u064a\u0631\u0647\u0645\u0627 \u062a\u0643\u0648\u0646 \u0642\u062f \u0627\u062e\u062a\u0631\u062a \u0627\u0644\u062e\u0633\u0627\u0631\u0629 \u0644\u0627 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631.","Some stores deliberately lose on the first order because the customer returns \u2014 that is the lifetime-value calculation. But under two non-negotiable conditions: a measured rather than assumed repeat rate, and sufficient liquidity. Without them you have chosen a loss, not an investment.")
