B.abV=new A.t("ec-m10-q1","\u0633\u0639\u0631 \u0661\u0662\u0660 \u0631\u064a\u0627\u0644\u064b\u0627\u060c \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0645\u0646\u062a\u062c \u0665\u0660\u060c \u0627\u0644\u062a\u063a\u0644\u064a\u0641 \u0665\u060c \u0627\u0644\u0634\u062d\u0646 \u0627\u0644\u0630\u064a \u062a\u062a\u062d\u0645\u0644\u0647 \u0662\u0665\u060c \u0631\u0633\u0648\u0645 \u0627\u0644\u062f\u0641\u0639 \u0663. \u0645\u0627 \u0647\u0627\u0645\u0634 \u0627\u0644\u0645\u0633\u0627\u0647\u0645\u0629\u061f","Price 120, product cost 50, packaging 5, shipping you absorb 25, payment fees 3. What is the contribution margin?",B.az6,B.agV,0,"\u0665\u0660 + \u0665 + \u0662\u0665 + \u0663 = \u0668\u0663\u060c \u0648\u0661\u0662\u0660 \u2212 \u0668\u0663 = \u0663\u0667 \u0631\u064a\u0627\u0644\u064b\u0627\u060c \u0623\u064a \u0646\u062d\u0648 \u0663\u0661\u066a. \u0648\u0647\u0630\u0627 \u0647\u0648 \u0645\u0627 \u064a\u063a\u0637\u064a \u0645\u0635\u0627\u0631\u064a\u0641\u0643 \u0627\u0644\u062b\u0627\u0628\u062a\u0629 \u062b\u0645 \u064a\u0635\u064a\u0631 \u0631\u0628\u062d\u064b\u0627 \u2014 \u0648\u0623\u064a \u062a\u0643\u0644\u0641\u0629 \u0627\u0643\u062a\u0633\u0627\u0628 \u0641\u0648\u0642 \u0663\u0667 \u062a\u0639\u0646\u064a \u062e\u0633\u0627\u0631\u0629 \u0639\u0644\u0649 \u0643\u0644 \u0639\u0645\u064a\u0644 \u062c\u062f\u064a\u062f.","50 + 5 + 25 + 3 = 83, and 120 \u2212 83 = 37, about 31%. That is what covers your fixed costs and then becomes profit \u2014 and any acquisition cost above 37 means a loss on every new customer.")
B.asU=s(["\u0627\u0644\u062a\u0634\u0627\u0624\u0645 \u0648\u062a\u0623\u062c\u064a\u0644 \u0627\u0644\u0628\u062f\u0621 \u062d\u062a\u0649 \u062a\u0633\u062a\u0642\u0631 \u0627\u0644\u0623\u0633\u0639\u0627\u0631","\u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f: \u0627\u0639\u0631\u0641 \u0623\u0631\u0642\u0627\u0645\u0643\u060c \u0648\u0627\u062d\u062a\u0641\u0638 \u0628\u0633\u064a\u0648\u0644\u0629\u060c \u0648\u0644\u0627 \u062a\u0628\u0646\u0650 \u0646\u0645\u0648\u0630\u062c\u0643 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u062a\u0643\u0644\u0641\u0629 \u0644\u0627 \u062a\u062a\u062d\u0643\u0645 \u0641\u064a\u0647\u0627","\u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0637\u0648\u064a\u0644 \u0627\u0644\u0623\u062c\u0644 \u0645\u0639 \u0645\u0648\u0631\u0651\u062f \u0648\u0627\u062d\u062f","\u0631\u0641\u0639 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0628\u0634\u0643\u0644 \u062f\u0648\u0631\u064a \u0644\u062a\u063a\u0637\u064a\u0629 \u0623\u064a \u0627\u0631\u062a\u0641\u0627\u0639"],t.s)
