B.aaX=new A.t("ec-m10-q8","\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u062c\u0639\u0644 \u0627\u0644\u0642\u0646\u0648\u0627\u062a \u0627\u0644\u0645\u0645\u0644\u0648\u0643\u0629 \xab\u0623\u0631\u062e\u0635 \u0631\u064a\u0627\u0644 \u0641\u064a \u0627\u0644\u062a\u0633\u0648\u064a\u0642\xbb\u061f",'What makes owned channels "the cheapest riyal in marketing"?',B.awa,B.av3,1,"\u062a\u0643\u0644\u0641\u062a\u0647\u0627 \u0627\u0644\u062d\u062f\u064a\u0629 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0635\u0641\u0631\u060c \u0648\u0627\u0644\u062c\u0645\u0647\u0648\u0631 \u0627\u0644\u0630\u064a \u0627\u0634\u062a\u0631\u0649 \u0645\u0646\u0643 \u0633\u0627\u0628\u0642\u064b\u0627 \u0647\u0648 \u0627\u0644\u0623\u0633\u0647\u0644 \u0625\u0642\u0646\u0627\u0639\u064b\u0627 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0644\u0643\u0646\u0647\u0627 \u062a\u062d\u062a\u0627\u062c \u0642\u0627\u0626\u0645\u0629 \u0645\u0628\u0646\u064a\u0629 \u0628\u0645\u0648\u0627\u0641\u0642\u0629 \u0635\u0631\u064a\u062d\u0629 \u0645\u0646 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0623\u0648\u0644.","Their marginal cost is near zero, and people who already bought from you are the easiest audience to convince again. But they need a list built with explicit consent from day one.")
B.aqo=s(["\u0627\u0644\u062c\u064a\u062f \u0623\u0642\u0635\u0631 \u0641\u064a\u064f\u0637\u0628\u0639 \u0623\u0633\u0631\u0639","\u0627\u0644\u062c\u064a\u062f \u0645\u0642\u0631\u0648\u0621 \u0644\u0644\u0625\u0646\u0633\u0627\u0646 (\u0641\u0626\u0629-\u0645\u0646\u062a\u062c-\u0645\u0642\u0627\u0633-\u0644\u0648\u0646)\u060c \u0648\u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064a \u064a\u0646\u0627\u0633\u0628 \u0627\u0644\u0622\u0644\u0629 \u0648\u064a\u064f\u062a\u0639\u0628 \u0645\u0646 \u064a\u062c\u0647\u0651\u0632 \u0627\u0644\u0637\u0644\u0628","\u0627\u0644\u062c\u064a\u062f \u064a\u062a\u0636\u0645\u0646 \u0633\u0639\u0631 \u0627\u0644\u0645\u0646\u062a\u062c","\u0644\u0627 \u0641\u0631\u0642 \u0645\u0627 \u062f\u0627\u0645 \u0641\u0631\u064a\u062f\u064b\u0627"],t.s)
