B.a9l=new A.t("cr-m7-q1","\u0645\u0627 \u0627\u0644\u0645\u0639\u064a\u0627\u0631 \u0627\u0644\u0630\u064a \u062a\u062a\u0628\u0639\u0647 \u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0631\u062f\u0627\u062f \u0627\u0644\u0627\u062b\u0646\u062a\u0627 \u0639\u0634\u0631\u0629 \u0623\u0648 \u0627\u0644\u0623\u0631\u0628\u0639 \u0648\u0627\u0644\u0639\u0634\u0631\u0648\u0646\u061f","What standard do the 12 or 24 recovery words follow?",B.aEk,B.azY,1,"\u0648\u0647\u064a \u0644\u064a\u0633\u062a \xab\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631\xbb \u0628\u0644 \u0627\u0644\u0628\u0630\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0634\u062a\u0642 \u0645\u0646\u0647\u0627 \u0643\u0644 \u0645\u0641\u0627\u062a\u064a\u062d\u0643 \u0648\u0639\u0646\u0627\u0648\u064a\u0646\u0643 \u0639\u0644\u0649 \u0643\u0644 \u0627\u0644\u0634\u0628\u0643\u0627\u062a \u2014 \u0648\u0644\u0647\u0630\u0627 \u064a\u0643\u0641\u064a \u062a\u0633\u0631\u064a\u0628\u0647\u0627 \u0644\u062e\u0633\u0627\u0631\u0629 \u0643\u0644 \u0634\u064a\u0621.","They are not a password but the seed from which all your keys and addresses on all networks are derived \u2014 which is why leaking them alone loses everything.")
B.ami=s(["\u0623\u0646\u0647\u0627 \u0623\u0633\u0631\u0639 \u0634\u0628\u0643\u0627\u062a \u0639\u0627\u0645\u0629","\u0623\u0646 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u064a\u0646 \u0641\u064a\u0647\u0627 \u0645\u0639\u0631\u0648\u0641\u0648\u0646 \u0648\u0645\u0635\u0631\u0651\u062d \u0644\u0647\u0645 \u0648\u0644\u0627 \u062a\u0648\u062c\u062f \u0639\u0645\u0644\u0629\u060c \u0648\u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062a\u0628\u0651\u0639 \u0633\u0644\u0627\u0633\u0644 \u0627\u0644\u0625\u0645\u062f\u0627\u062f \u0648\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0634\u0647\u0627\u062f\u0627\u062a \u0648\u062a\u0633\u0648\u064a\u0629 \u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a","\u0623\u0646\u0647\u0627 \u062a\u0639\u062a\u0645\u062f \u0625\u062b\u0628\u0627\u062a \u0627\u0644\u0639\u0645\u0644 \u062d\u0635\u0631\u064a\u064b\u0627","\u0623\u0646\u0647\u0627 \u0645\u0641\u062a\u0648\u062d\u0629 \u0644\u0623\u064a \u0634\u062e\u0635 \u0644\u0644\u062a\u062d\u0642\u0642"],t.s)
