B.aab=new A.t("cr-m10-q6","\u0643\u064a\u0641 \u062a\u062a\u0635\u0631\u0641 \u062a\u062c\u0627\u0647 \u0645\u0648\u0627\u0641\u0642\u0629 \u063a\u064a\u0631 \u0645\u062d\u062f\u0648\u062f\u0629 \u0645\u0646\u062d\u062a\u0647\u0627 \u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0633\u062a\u062e\u062f\u0645\u062a\u0647 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629\u061f","What do you do about an unlimited approval you granted to an app you used once?",B.ad9,B.axJ,1,"\u062d\u0630\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0627 \u064a\u0644\u063a\u064a \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u0645\u0646\u0648\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0644\u0633\u0644\u0629. \u0631\u0627\u062c\u0639 \u0645\u0648\u0627\u0641\u0642\u0627\u062a\u0643 \u062f\u0648\u0631\u064a\u064b\u0627\u060c \u0648\u062d\u062f\u0651\u062f \u0645\u0628\u0644\u063a\u064b\u0627 \u0645\u0639\u064a\u0651\u0646\u064b\u0627 \u0628\u062f\u0644 \xab\u063a\u064a\u0631 \u0645\u062d\u062f\u0648\u062f\xbb \u0643\u0644\u0645\u0627 \u0623\u062a\u064a\u062d \u0630\u0644\u0643.",'Removing the app does not revoke the on-chain allowance. Review your approvals periodically, and set a specific allowance instead of "unlimited" whenever offered.')
B.ahO=s(["\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0628\u064a\u0636\u0627\u0621 \u0644\u0645\u0634\u0631\u0648\u0639","\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062f\u0648\u0631\u0629 \u0643\u0627\u0645\u0644\u0629 \u0639\u0644\u0649 \u0634\u0628\u0643\u0629 \u0627\u062e\u062a\u0628\u0627\u0631: \u0625\u0646\u0634\u0627\u0621 \u0645\u062d\u0641\u0638\u0629\u060c \u0648\u0625\u0631\u0633\u0627\u0644 \u0645\u0639\u0627\u0645\u0644\u0629\u060c \u0648\u062f\u0641\u0639 \u063a\u0627\u0632\u060c \u0648\u0642\u0631\u0627\u0621\u0629 \u0645\u0633\u062a\u0643\u0634\u0641 \u0643\u062a\u0644","\u0634\u0631\u0627\u0621 \u0645\u0628\u0644\u063a \u0635\u063a\u064a\u0631 \u062c\u062f\u064b\u0627 \u0648\u0628\u064a\u0639\u0647","\u0645\u0642\u0627\u0631\u0646\u0629 \u0631\u0633\u0648\u0645 \u0639\u062f\u0629 \u0634\u0628\u0643\u0627\u062a"],t.s)
