B.aaS=new A.t("fx-m5-q6","\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u062c\u0628 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0625\u0628\u0642\u0627\u0621 \u0623\u064a \u0645\u0631\u0643\u0632 \u0645\u0641\u062a\u0648\u062d\u064b\u0627 \u0644\u0644\u064a\u0644\u0629\u061f","What must be checked before holding any position overnight?",B.aDi,B.asX,1,"\u0641\u0641\u064a \u064a\u0648\u0645 \u0645\u062d\u062f\u062f \u0645\u0646 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u062a\u064f\u062d\u062a\u0633\u0628 \u0623\u064a\u0627\u0645 \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0641\u062a\u0646\u0634\u0623 \u062a\u0643\u0644\u0641\u0629 \u0645\u0636\u0627\u0639\u0641\u0629 \u062a\u0641\u0627\u062c\u0626 \u0645\u0646 \u0644\u0627 \u064a\u0639\u0631\u0641 \u0627\u0644\u062c\u062f\u0648\u0644.","On one specific weekday the weekend days are charged at once, producing a multiplied cost that surprises anyone unaware of the schedule.")
B.ayu=s(["\u0643\u0634\u0648\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0634\u0647\u0631\u064a\u0629\u060c \u0648\u0633\u062c\u0644 \u0627\u0644\u0635\u0641\u0642\u0627\u062a \u0628\u0623\u0648\u0642\u0627\u062a\u0647\u0627 \u0648\u0623\u0633\u0639\u0627\u0631\u0647\u0627 \u0648\u062a\u0643\u0627\u0644\u064a\u0641\u0647\u0627\u060c \u0648\u0646\u0633\u062e \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0643\u0645\u0627 \u0643\u0627\u0646\u062a\u060c \u0648\u0627\u0644\u0645\u0631\u0627\u0633\u0644\u0627\u062a \u2014 \u0644\u0623\u0646 \u0627\u0644\u0633\u062c\u0644 \u0643\u0644 \u0645\u0627 \u062a\u0645\u0644\u0643\u0647 \u0639\u0646\u062f \u0623\u064a \u0646\u0632\u0627\u0639","\u0644\u0642\u0637\u0627\u062a \u0627\u0644\u0634\u0627\u0634\u0629 \u0644\u0644\u0623\u0631\u0628\u0627\u062d \u0641\u0642\u0637","\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0633\u0648\u064a\u0642 \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0645\u0646 \u0627\u0644\u0648\u0633\u064a\u0637","\u0644\u0627 \u062d\u0627\u062c\u0629 \u0644\u0633\u062c\u0644\u0627\u062a \u0644\u0623\u0646 \u0627\u0644\u0645\u0646\u0635\u0629 \u062a\u062d\u062a\u0641\u0638 \u0628\u0643\u0644 \u0634\u064a\u0621"],t.s)
