B.ac0=new A.t("fx-m5-q7","\u0645\u0627 \u0627\u0644\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647\u0627\u060c \u0648\u0644\u0645\u0627\u0630\u0627\u061f","Which records must you keep, and why?",B.ayu,B.ay7,0,"\u0648\u0648\u062b\u0651\u0642 \u0643\u0644 \u0639\u0645\u0644\u064a\u0629 \u0633\u062d\u0628 \u0623\u064a\u0636\u064b\u0627\u060c \u0646\u0627\u062c\u062d\u0629 \u0643\u0627\u0646\u062a \u0623\u0648 \u0645\u062a\u0623\u062e\u0631\u0629\u060c \u0628\u062a\u0648\u0627\u0631\u064a\u062e\u0647\u0627. \u0641\u0627\u0644\u0633\u062d\u0628 \u0627\u0644\u0645\u0645\u0627\u0637\u0644 \u0623\u0648\u0644 \u0639\u0644\u0627\u0645\u0629 \u0639\u0645\u0644\u064a\u0629 \u0639\u0644\u0649 \u062a\u0639\u062b\u0651\u0631 \u0634\u0631\u0643\u0629\u060c \u0648\u0647\u0648 \u064a\u0633\u0628\u0642 \u0639\u0627\u062f\u0629\u064b \u0623\u064a \u0625\u0639\u0644\u0627\u0646 \u0631\u0633\u0645\u064a.","Document every withdrawal too, successful or delayed, with dates. A stalling withdrawal is the first practical sign of trouble at a firm, and it usually precedes any official announcement.")
B.aBY=s(["\u0644\u0623\u0646 \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u0631\u0642\u0627\u0628\u064a\u0629 \u0644\u0627 \u062a\u0645\u0644\u0643 \u0635\u0644\u0627\u062d\u064a\u0627\u062a","\u0644\u0623\u0646 \u0627\u0644\u0636\u062d\u0627\u064a\u0627 \u064a\u0634\u0639\u0631\u0648\u0646 \u0628\u0645\u0633\u0624\u0648\u0644\u064a\u062a\u0647\u0645 \u0639\u0646 \u0627\u0644\u0642\u0631\u0627\u0631 \u0641\u0644\u0627 \u064a\u0628\u0644\u0651\u063a\u0648\u0646\u060c \u0648\u062a\u064f\u0633\u0645\u0649 \u0627\u0644\u062e\u0633\u0627\u0631\u0629 \xab\u0635\u0641\u0642\u0629 \u062e\u0627\u0633\u0631\u0629\xbb \u0641\u062a\u0628\u062f\u0648 \u0646\u062a\u064a\u062c\u0629 \u0633\u0648\u0642 \u0644\u0627 \u062c\u0631\u064a\u0645\u0629","\u0644\u0623\u0646 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u062a\u0633\u0645\u062d \u0628\u0647\u0627 \u0635\u0631\u0627\u062d\u0629","\u0644\u0623\u0646 \u0627\u0644\u0645\u0628\u0627\u0644\u063a \u0635\u063a\u064a\u0631\u0629 \u0648\u0644\u0627 \u062a\u0633\u062a\u062d\u0642 \u0627\u0644\u0628\u0644\u0627\u063a"],t.s)
