B.aam=new A.t("fx-m6-q1","\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0627\u0633\u0645\u064a\u0629 (notional) \u0648\u0644\u0645\u0627\u0630\u0627 \u062a\u0628\u062f\u0623 \u0645\u0646\u0647\u0627 \u0643\u0644 \u062a\u062d\u0644\u064a\u0644\u0627\u062a \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629\u061f","What is notional value and why does every risk analysis start from it?",B.aw8,B.alU,1,"\u0645\u0646 \u064a\u0641\u062a\u062d \u0639\u0642\u062f\u064b\u0627 \u0642\u064a\u0627\u0633\u064a\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u064a\u062a\u062d\u0643\u0645 \u0628\u0646\u062d\u0648 \u0661\u0660\u0660 \u0623\u0644\u0641 \u062f\u0648\u0644\u0627\u0631 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0629 \u062d\u062a\u0649 \u0644\u0648 \u0643\u0627\u0646 \u0631\u0635\u064a\u062f\u0647 \u0661\u066c\u0660\u0660\u0660 \u0641\u0642\u0637. \u0648\u0644\u0647\u0630\u0627 \u062a\u064f\u062d\u0633\u0628 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629 \u0645\u0646 \u0627\u0644\u0627\u0633\u0645\u064a\u0629 \u0644\u0627 \u0645\u0646 \u0627\u0644\u0631\u0635\u064a\u062f.","Someone opening one standard lot controls about 100,000 of currency even if their balance is only 1,000. That is why risk is computed from the notional rather than the balance.")
B.anm=s(["\u062b\u0645\u0646 \u0634\u0631\u0627\u0621 \u0627\u0644\u0639\u0645\u0644\u0629","\u0647\u0627\u0645\u0634: \u0636\u0645\u0627\u0646 \u064a\u062d\u062a\u062c\u0632\u0647 \u0627\u0644\u0648\u0633\u064a\u0637 \u0644\u062a\u063a\u0637\u064a\u0629 \u062e\u0633\u0627\u0631\u0629 \u0645\u062d\u062a\u0645\u0644\u0629 \u0648\u064a\u064f\u0639\u0627\u062f \u0625\u0644\u064a\u0643 \u0639\u0646\u062f \u0627\u0644\u0625\u063a\u0644\u0627\u0642 \u0628\u0639\u062f \u062a\u0633\u0648\u064a\u0629 \u0627\u0644\u0646\u062a\u064a\u062c\u0629","\u0631\u0633\u0645 \u062f\u062e\u0648\u0644 \u063a\u064a\u0631 \u0645\u0633\u062a\u0631\u062f","\u0648\u062f\u064a\u0639\u0629 \u062a\u062f\u0631\u0651 \u0641\u0627\u0626\u062f\u0629"],t.s)
B.ajE=s(["The purchase price of the currency","Margin: collateral held by the broker to cover a potential loss, returned at close once the result is settled","A non-refundable entry fee","An interest-bearing deposit"],t.s)
B.aaO=new A.t("fx-m6-q2","\u0645\u0627 \u0627\u0644\u062a\u0648\u0635\u064a\u0641 \u0627\u0644\u062f\u0642\u064a\u0642 \u0644\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0630\u064a \xab\u062a\u0648\u062f\u0639\u0647\xbb \u0639\u0646\u062f \u0641\u062a\u062d \u0645\u0631\u0643\u0632 \u0628\u0631\u0627\u0641\u0639\u0629\u061f",'What exactly is the amount you "deposit" when opening a leveraged position?',B.anm,B.ajE,1,"\u0648\u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0642\u0631\u0636 \u0644\u0627 \u0642\u062f\u0631\u0629 \u062e\u0627\u0631\u0642\u0629: \u0661:\u0661\u0660\u0660 \u062a\u0639\u0646\u064a \u0623\u0646 \u0661\u066c\u0660\u0660\u0660 \u062f\u0648\u0644\u0627\u0631 \u062a\u0641\u062a\u062d \u0645\u0631\u0643\u0632\u064b\u0627 \u0628\u0640\u0661\u0660\u0660 \u0623\u0644\u0641. \u0648\u0645\u0627 \u064a\u064f\u0642\u062f\u064e\u0651\u0645 \u0643\u0640\xab\u0642\u0648\u0629 \u0634\u0631\u0627\u0626\u064a\u0629 \u0623\u0643\u0628\u0631\xbb \u0647\u0648 \u062d\u0631\u0641\u064a\u064b\u0627 \xab\u0645\u0633\u0627\u0641\u0629 \u0623\u0642\u0635\u0631 \u0628\u064a\u0646\u0643 \u0648\u0628\u064a\u0646 \u0627\u0644\u062a\u0635\u0641\u064a\u0629\xbb \u2014 \u0648\u0635\u0641 \u062d\u0633\u0627\u0628\u064a \u0644\u0627 \u0631\u0623\u064a \u062a\u062d\u0630\u064a\u0631\u064a.",'Leverage is a loan, not a superpower: 1:100 means 1,000 opens a 100,000 position. What is presented as "greater buying power" is literally "a shorter distance between you and liquidation" \u2014 an arithmetic description, not a cautionary opinion.')
B.auh=s(["\u0627\u0644\u0631\u0642\u0645 \u0645\u062e\u062a\u0644\u0642 \u0623\u0635\u0644\u064b\u0627","\u0627\u0644\u0631\u0642\u0645 \u0635\u062d\u064a\u062d \u0644\u0643\u0646\u0647 \u0648\u0635\u0641 \u0628\u0646\u064a\u0629 \u062a\u062d\u062a\u064a\u0629 \u0644\u0627 \u062f\u0644\u064a\u0644 \u0641\u0631\u0635\u0629 \u0634\u062e\u0635\u064a\u0629\u061b \u0627\u0644\u0633\u064a\u0648\u0644\u0629 \u0627\u0644\u0636\u062e\u0645\u0629 \u064a\u0635\u0646\u0639\u0647\u0627 \u0645\u062d\u062a\u0631\u0641\u0648\u0646 \u0648\u0623\u0633\u0639\u0627\u0631 \u062a\u0645\u062a\u0635 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0628\u0633\u0631\u0639\u0629","\u0627\u0644\u0631\u0642\u0645 \u0642\u062f\u064a\u0645 \u0648\u0644\u0645 \u064a\u064f\u062d\u062f\u064e\u0651\u062b \u0645\u0646\u0630 \u0627\u0644\u062a\u0633\u0639\u064a\u0646\u064a\u0627\u062a","\u0627\u0644\u0631\u0642\u0645 \u064a\u0634\u0645\u0644 \u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0623\u0633\u0647\u0645 \u0623\u064a\u0636\u064b\u0627"],t.s)
