B.a7W=new A.t("fx-m10-q8","\u0645\u0627 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0641\u0648\u0631 \u0627\u0643\u062a\u0634\u0627\u0641 \u062a\u0639\u0631\u0636\u0643 \u0644\u0644\u0627\u062d\u062a\u064a\u0627\u0644\u061f","What are the right steps the moment you discover you have been defrauded?",B.agJ,B.aj4,1,"\u0648\u0627\u0644\u062a\u0623\u062e\u064a\u0631 \u064a\u0642\u0644\u0644 \u0641\u0631\u0635 \u0627\u0644\u0627\u0633\u062a\u0631\u062f\u0627\u062f \u0623\u0643\u062b\u0631 \u0645\u0646 \u0623\u064a \u0639\u0627\u0645\u0644 \u0622\u062e\u0631. \u0648\u0627\u062d\u0630\u0631 \u0645\u0646 \u0646\u0645\u0637 \u0627\u062d\u062a\u064a\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0631\u062f\u0627\u062f \u0627\u0644\u0630\u064a \u064a\u0644\u064a\u0647: \u0631\u0633\u0627\u0644\u0629 \u062a\u0639\u0631\u0636 \u0625\u0639\u0627\u062f\u0629 \u0645\u0627 \u062e\u0633\u0631\u062a\u0647 \u0645\u0642\u0627\u0628\u0644 \u0631\u0633\u0648\u0645 \u0645\u0642\u062f\u0651\u0645\u0629.","Delay reduces recovery chances more than any other factor. And beware the recovery scam that follows: a message offering to return what you lost in exchange for an upfront fee.")
B.arF=s(["\u062f\u0642\u0629 \u0627\u0644\u062a\u0646\u0628\u0624 \u0628\u0627\u0644\u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0642\u0627\u062f\u0645","\u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u0648\u0627\u0644\u062a\u0648\u0642\u064a\u062a \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0627\u0644\u062a\u0646\u0628\u0624","\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0639\u0627\u062f\u0644\u0629 \u0644\u0644\u0639\u0645\u0644\u0629","\u0642\u064a\u0627\u0633 \u0623\u062b\u0631 \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0632\u0648\u062c"],t.s)
