B.a8f=new A.t("st-m1-q1","\u0645\u0627\u0630\u0627 \u062a\u0645\u0644\u0643 \u0641\u0639\u0644\u064b\u0627 \u062d\u064a\u0646 \u062a\u0634\u062a\u0631\u064a \u0633\u0647\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627\u061f","What do you actually own when you buy one share?",B.alB,B.aF0,0,"\u0627\u0644\u0633\u0647\u0645 \u0645\u0644\u0643\u064a\u0629\u060c \u0644\u0627 \u0642\u0631\u0636 \u0648\u0644\u0627 \u0639\u0642\u062f. \u062d\u0627\u0645\u0644 \u0627\u0644\u0633\u0646\u062f \u0647\u0648 \u0627\u0644\u062f\u0627\u0626\u0646 \u0627\u0644\u0630\u064a \u064a\u064f\u0648\u0639\u062f \u0628\u0641\u0627\u0626\u062f\u0629\u061b \u0623\u0645\u0627 \u0627\u0644\u0645\u0633\u0627\u0647\u0645 \u0641\u064a\u0645\u0644\u0643 \u062d\u0635\u0629 \u0641\u064a \u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0648\u0645\u0627 \u064a\u062a\u0628\u0642\u0651\u0649 \u0628\u0639\u062f \u0633\u062f\u0627\u062f \u0627\u0644\u062c\u0645\u064a\u0639.","A share is ownership, not a loan and not a contract. A bondholder is the lender who is promised interest; a shareholder owns a stake in the equity and a claim on what is left after everyone else is paid.")
B.at_=s(["\u0634\u0631\u0643\u0629 \xab\u0623\xbb\u060c \u0644\u0623\u0646 \u0642\u064a\u0645\u062a\u0647\u0627 \u0627\u0644\u0633\u0648\u0642\u064a\u0629 \u0639\u0634\u0631\u0629 \u0645\u0644\u064a\u0627\u0631\u0627\u062a \u0645\u0642\u0627\u0628\u0644 \u0645\u0644\u064a\u0627\u0631 \u0648\u0627\u062d\u062f","\u0634\u0631\u0643\u0629 \xab\u0628\xbb\u060c \u0644\u0623\u0646 \u0633\u0639\u0631 \u0633\u0647\u0645\u0647\u0627 \u0623\u0639\u0644\u0649 \u0628\u0645\u0626\u0629 \u0645\u0631\u0629","\u0645\u062a\u0633\u0627\u0648\u064a\u062a\u0627\u0646\u060c \u0644\u0623\u0646 \u062d\u0627\u0635\u0644 \u0627\u0644\u0636\u0631\u0628 \u0648\u0627\u062d\u062f","\u0644\u0627 \u064a\u0645\u0643\u0646 \u0645\u0639\u0631\u0641\u0629 \u0630\u0644\u0643 \u0645\u0646 \u0633\u0639\u0631 \u0627\u0644\u0633\u0647\u0645 \u0648\u0639\u062f\u062f\u0647"],t.s)
