B.a6L=new A.t("st-m1-q2","\u0634\u0631\u0643\u0629 \xab\u0623\xbb \u0633\u0639\u0631 \u0633\u0647\u0645\u0647\u0627 \u0661\u0660 \u062f\u0648\u0644\u0627\u0631\u0627\u062a \u0648\u0644\u062f\u064a\u0647\u0627 \u0645\u0644\u064a\u0627\u0631 \u0633\u0647\u0645. \u0648\u0634\u0631\u0643\u0629 \xab\u0628\xbb \u0633\u0639\u0631 \u0633\u0647\u0645\u0647\u0627 \u0661\u066c\u0660\u0660\u0660 \u062f\u0648\u0644\u0627\u0631 \u0648\u0644\u062f\u064a\u0647\u0627 \u0645\u0644\u064a\u0648\u0646 \u0633\u0647\u0645. \u0623\u064a\u0651\u0647\u0645\u0627 \u0623\u0643\u0628\u0631\u061f","Company A trades at $10 with a billion shares. Company B trades at $1,000 with a million shares. Which is larger?",B.at_,B.at1,0,"\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629 \u0647\u064a \u0627\u0644\u0633\u0639\u0631 \u0645\u0636\u0631\u0648\u0628\u064b\u0627 \u0641\u064a \u0639\u062f\u062f \u0627\u0644\u0623\u0633\u0647\u0645: \u0661\u0660 \xd7 \u0645\u0644\u064a\u0627\u0631 = \u0639\u0634\u0631\u0629 \u0645\u0644\u064a\u0627\u0631\u0627\u062a\u060c \u0648\u0661\u066c\u0660\u0660\u0660 \xd7 \u0645\u0644\u064a\u0648\u0646 = \u0645\u0644\u064a\u0627\u0631. \u0633\u0639\u0631 \u0627\u0644\u0633\u0647\u0645 \u0648\u062d\u062f\u0647 \u0644\u0627 \u064a\u0642\u0648\u0644 \u0634\u064a\u0626\u064b\u0627 \u0639\u0646 \u062d\u062c\u0645 \u0627\u0644\u0634\u0631\u0643\u0629.","Market capitalisation is price times share count: 10 x a billion = ten billion, and 1,000 x a million = one billion. A share price alone says nothing about the size of a company.")
B.ayf=s(["\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0645\u0646\u0639 \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646 \u0645\u0646 \u0623\u062e\u0630 \u0623\u0631\u0628\u0627\u062d \u0627\u0644\u0634\u0631\u0643\u0629","\u062d\u062c\u0645 \u0627\u0644\u0646\u0642\u062f \u0627\u0644\u0645\u062a\u0648\u0641\u0651\u0631 \u0641\u064a \u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0634\u0631\u0643\u0629","\u0639\u062f\u062f \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u062a\u064a \u062a\u0639\u0645\u0644 \u0641\u064a\u0647\u0627 \u0627\u0644\u0634\u0631\u0643\u0629","\u0645\u062f\u0649 \u062a\u0642\u0644\u0651\u0628 \u0633\u0639\u0631 \u0627\u0644\u0633\u0647\u0645 \u062e\u0644\u0627\u0644 \u0627\u0644\u0633\u0646\u0629"],t.s)
