B.aar=new A.t("st-m2-q4","\u0634\u0631\u0643\u0629 \u064a\u0631\u062a\u0641\u0639 \u0625\u064a\u0631\u0627\u062f\u0647\u0627 \u0628\u0633\u0631\u0639\u0629 \u0648\u062a\u0632\u062f\u0627\u062f \u062e\u0633\u0627\u0631\u062a\u0647\u0627 \u0643\u0644\u0645\u0627 \u0643\u0628\u0631\u062a. \u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0642\u0648\u0644\u0647 \u0630\u0644\u0643\u061f","A company grows revenue fast and loses more money as it grows. What does that say?",B.aCM,B.auF,0,"\u0627\u0644\u0625\u064a\u0631\u0627\u062f \u0623\u0633\u0647\u0644 \u0631\u0642\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0631\u064a\u0643: \u062e\u0641\u0651\u0636 \u0627\u0644\u0633\u0639\u0631 \u0628\u0645\u0627 \u064a\u0643\u0641\u064a \u0648\u0633\u062a\u0628\u064a\u0639 \u0623\u0643\u062b\u0631. \u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u0635\u062d\u064a\u062d \u0647\u0648 \u0647\u0644 \u064a\u062a\u062d\u0633\u0651\u0646 \u0627\u0644\u0647\u0627\u0645\u0634 \u0645\u0639 \u0627\u0644\u0646\u0645\u0648 \u2014 \u0641\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0633\u0644\u064a\u0645 \u064a\u0635\u0628\u062d \u0623\u0643\u062b\u0631 \u0631\u0628\u062d\u064a\u0629 \u0643\u0644\u0645\u0627 \u0643\u0628\u0631.","Revenue is the easiest number to move: cut the price enough and you will sell more. The right question is whether the margin improves with growth \u2014 a sound business becomes more profitable as it gets bigger.")
B.aux=s(["\u064a\u0632\u064a\u0644 \u0627\u0644\u062e\u0637\u0631 \u0627\u0644\u062e\u0627\u0635 \u0628\u0634\u0631\u0643\u0629 \u0628\u0639\u064a\u0646\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0632\u064a\u0644 \u062e\u0637\u0631 \u0627\u0644\u0633\u0648\u0642 \u0643\u0643\u0644","\u064a\u0632\u064a\u0644 \u062e\u0637\u0631 \u0627\u0644\u0633\u0648\u0642 \u0643\u0643\u0644\u060c \u0648\u0644\u0627 \u064a\u0632\u064a\u0644 \u0627\u0644\u062e\u0637\u0631 \u0627\u0644\u062e\u0627\u0635","\u064a\u0632\u064a\u0644 \u0627\u0644\u0646\u0648\u0639\u064a\u0646 \u0645\u0639\u064b\u0627 \u0628\u0627\u0644\u0643\u0627\u0645\u0644","\u0644\u0627 \u064a\u0632\u064a\u0644 \u0623\u064a \u062e\u0637\u0631\u060c \u0628\u0644 \u064a\u0642\u0644\u0651\u0644 \u0627\u0644\u0639\u0627\u0626\u062f \u0641\u0642\u0637"],t.s)
