B.a7C=new A.t("st-m2-q5","\u0645\u0627 \u0627\u0644\u062e\u0637\u0631 \u0627\u0644\u0630\u064a \u064a\u0632\u064a\u0644\u0647 \u0627\u0644\u062a\u0646\u0648\u064a\u0639\u060c \u0648\u0645\u0627 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0632\u064a\u0644\u0647\u061f","Which risk does diversification remove, and which does it not?",B.aux,B.aE_,0,"\u0648\u0627\u0644\u0646\u0642\u0637\u0629 \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0623\u0646 \u0627\u0644\u0633\u0648\u0642 \u0644\u0627 \u064a\u0643\u0627\u0641\u0626\u0643 \u0639\u0644\u0649 \u062a\u062d\u0645\u0651\u0644 \u0627\u0644\u062e\u0637\u0631 \u0627\u0644\u062e\u0627\u0635\u060c \u0644\u0623\u0646\u0647 \u062e\u0637\u0631 \u0643\u0627\u0646 \u0628\u0625\u0645\u0643\u0627\u0646\u0643 \u0625\u0632\u0627\u0644\u062a\u0647 \u0645\u062c\u0627\u0646\u064b\u0627 \u0628\u0627\u0644\u062a\u0646\u0648\u064a\u0639: \u0645\u062e\u0627\u0637\u0631\u0629 \u0625\u0636\u0627\u0641\u064a\u0629 \u0628\u0644\u0627 \u0639\u0627\u0626\u062f \u0645\u062a\u0648\u0642\u0651\u0639 \u0625\u0636\u0627\u0641\u064a.","The subtle point is that the market does not reward you for carrying company-specific risk, because it is a risk you could have removed for free by diversifying: extra risk with no extra expected return.")
B.akq=s(["\u0627\u0644\u062d\u0643\u0645 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0642\u0645\u0629 \u0627\u0644\u062f\u0648\u0631\u0629 \u062d\u064a\u0646 \u062a\u0628\u062f\u0648 \u0623\u0631\u0628\u0627\u062d\u0647\u0627 \u0647\u0627\u0626\u0644\u0629 \u0648\u0645\u0643\u0631\u0651\u0631\u0647\u0627 \u0645\u0646\u062e\u0641\u0636\u064b\u0627","\u0627\u0644\u062d\u0643\u0645 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0642\u0627\u0639 \u0627\u0644\u062f\u0648\u0631\u0629 \u062d\u064a\u0646 \u062a\u0628\u062f\u0648 \u062e\u0627\u0633\u0631\u0629","\u0645\u0642\u0627\u0631\u0646\u062a\u0647\u0627 \u0628\u0634\u0631\u0643\u0627\u062a \u0645\u0646 \u0627\u0644\u0642\u0637\u0627\u0639 \u0646\u0641\u0633\u0647","\u0642\u0631\u0627\u0621\u0629 \u0642\u0648\u0627\u0626\u0645\u0647\u0627 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u062e\u0645\u0633 \u0633\u0646\u0648\u0627\u062a"],t.s)
